#include "mcts.h"
#include "late.h"
using namespace v2;
int main(int argc,char**argv){try{if(argc!=6)throw std::runtime_error("MODEL MODE SEED COUNT OUT");init();Learner m;m.load(argv[1]);std::string mode=argv[2];Reference full(m);MCTS mc(m);v8late::Search late(m);uint32_t first=std::stoul(argv[3]);int n=std::stoi(argv[4]);std::ofstream out(argv[5]);for(int i=0;i<n;i++){RNG rng{first+uint32_t(i)};Game g;g.reset(rng);Counts c=opening(g);double start=cpuNow();while(!g.over&&high(g.b)<14&&g.turns<6000){Answer a;if(high(g.b)>=12||mode=="v4"){auto l=late.choose(g.b,g.next,c);a={l.value,l.direction};}else if(mode=="mcts")a=mc.choose(g.b,g.next,c,uint32_t((first+i)*2654435761u)^uint32_t(g.turns*2246822519u));else a=full.choose(g.b,g.next,c);if(a.direction<0)throw std::runtime_error("illegal");g.advance(move(g.b,a.direction),rng);c=observe(c,g.next);}if(!g.over&&high(g.b)<14)throw std::runtime_error("truncated");out<<"{\"seed\":"<<first+i<<",\"maxRank\":"<<high(g.b)<<",\"moves\":"<<g.turns<<",\"cpu\":"<<cpuNow()-start<<"}"<<std::endl;}}catch(const std::exception&e){std::cerr<<e.what()<<std::endl;return 1;}}
